/**
 * "hls.js/light" — та сама бібліотека без альтернативних аудіодоріжок, субтитрів і DRM
 * (камерам вони не потрібні, а чанк удвічі менший). Типів для цього входу в пакеті немає,
 * але API повністю збігається з повною збіркою.
 */
declare module "hls.js/light" {
  export * from "hls.js";
  export { default } from "hls.js";
}
